while ((4./3.)*std::abs(m_int*m_h - m_old*m_h*2) > precision) {
    m_old = m_int;
    N = N*2;
    m_h = std::abs(b-a)/N;
    for (int i = 0; (a+m_h+i*2*m_h) < b; ++i) {
        m_int += f->eval(a + m_h + 2*m_h*i);
    }
}
return m_int * m_h;

